#define R iResolution
#define TAU 6.28318530718
#define white vec3(1.)

// convert cartesic to polar coordinates (.x = normalized angle 0...1, .y = length)
vec2 polar ( vec2 cartesic ) {
    return vec2( atan(cartesic.x, cartesic.y)/6.28318530718, sqrt(cartesic.x*cartesic.x+cartesic.y*cartesic.y));
}

float spikes( float value, float pos, float width ) {
   // return smoothstep( width/2., 0., abs(mod(value-pos,0.1)) );
     return smoothstep( 0.5*width, 0., abs( mod(value-pos,2.*width)-width ) );  // antialias fix :)
}

vec3 brighten( vec3 color) {
    return color / max(max(color.r,color.g),color.b);
}

void mainImage( out vec4 C, in vec2 S )
{

    // canvas coordinates
    float line_width = 1.5/R.y;
    float t = fract(iTime*0.01);
    vec2 uv = S.xy/vec2(R.y);
    vec2 center = .5*R.xy/R.y;


    vec2 A = polar(uv-center + vec2(0.5,0) );
    vec2 B = polar(uv-center - vec2(0.5,0));


    vec3 pattern = vec3(
        0.5 + 0.5*cos((A.x+t)*TAU*6.) * sin((A.y-t)*TAU*6.)  *  sin((B.x-t)*TAU*6.) * cos((B.y+t)*TAU*6.),
        0.5 + 0.5*sin((A.x+t)*TAU*5.) * cos((A.y-t)*TAU*7.)  *  cos((B.x-t)*TAU*7.) * sin((B.y+t)*TAU*5.),
        0.5 + 0.5*cos((A.x+t)*TAU*4.) * sin((A.y-t)*TAU*8.)  *  sin((B.x-t)*TAU*8.) * cos((B.y+t)*TAU*4.)
    );    

    int  cal_id = int(floor(iTime))%6+1;  // 1,2,3,4,5,6,1,... --> 001,010,011,100,101,110
    vec3 chg_color = mix(
        vec3(float(cal_id & 4)*0.25,float(cal_id & 2)*0.5,float(cal_id & 1)), // binary color_id
        white,
        1.-abs(fract(iTime))
    );

     // Output to screen
    C.rgb = 1.5*pattern * spikes(fract(iTime*0.1), pattern.r, 0.05) * chg_color;
 //   C.rgb = vec3( spikes(uv.x, 0.0, 0.05 ));  // show what spikes() does
   C.a = 1.;
}
